-- Identity core. IDs are generated by the application; no database extension
-- or server-side random identifier function is required.

CREATE TABLE users (
    id uuid PRIMARY KEY,
    email text NOT NULL,
    normalized_email text NOT NULL,
    display_name text NOT NULL,
    status text NOT NULL DEFAULT 'active',
    is_instance_admin boolean NOT NULL DEFAULT FALSE,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    disabled_at timestamptz,
    CONSTRAINT users_normalized_email_unique UNIQUE (normalized_email),
    CONSTRAINT users_email_length_check
        CHECK (
            email = btrim(email)
            AND email !~ '[[:cntrl:]]'
            AND char_length(email) BETWEEN 3 AND 320
        ),
    CONSTRAINT users_normalized_email_check
        CHECK (
            normalized_email = lower(btrim(email))
            AND char_length(normalized_email) BETWEEN 3 AND 320
        ),
    CONSTRAINT users_display_name_check
        CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 200),
    CONSTRAINT users_status_check
        CHECK (status IN ('active', 'disabled')),
    CONSTRAINT users_lifecycle_check
        CHECK (
            (status = 'active' AND disabled_at IS NULL)
            OR (status = 'disabled' AND disabled_at IS NOT NULL)
        ),
    CONSTRAINT users_timestamps_check
        CHECK (
            updated_at >= created_at
            AND (disabled_at IS NULL OR disabled_at >= created_at)
            AND (disabled_at IS NULL OR updated_at >= disabled_at)
        )
);

CREATE INDEX users_active_instance_admin_idx
    ON users (id)
    WHERE status = 'active' AND is_instance_admin;

CREATE TABLE local_password_credentials (
    user_id uuid PRIMARY KEY,
    password_verifier text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT local_password_credentials_user_fk
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT local_password_credentials_verifier_check
        CHECK (
            password_verifier LIKE '$argon2id$%'
            AND char_length(password_verifier) BETWEEN 32 AND 1024
        ),
    CONSTRAINT local_password_credentials_timestamps_check
        CHECK (updated_at >= created_at)
);

CREATE TABLE oidc_providers (
    id uuid PRIMARY KEY,
    display_name text NOT NULL,
    issuer text NOT NULL,
    status text NOT NULL DEFAULT 'active',
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    disabled_at timestamptz,
    CONSTRAINT oidc_providers_display_name_unique UNIQUE (display_name),
    CONSTRAINT oidc_providers_issuer_unique UNIQUE (issuer),
    CONSTRAINT oidc_providers_display_name_check
        CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 200),
    CONSTRAINT oidc_providers_issuer_check
        CHECK (
            issuer = btrim(issuer)
            AND char_length(issuer) BETWEEN 8 AND 2048
        ),
    CONSTRAINT oidc_providers_status_check
        CHECK (status IN ('active', 'disabled')),
    CONSTRAINT oidc_providers_lifecycle_check
        CHECK (
            (status = 'active' AND disabled_at IS NULL)
            OR (status = 'disabled' AND disabled_at IS NOT NULL)
        ),
    CONSTRAINT oidc_providers_timestamps_check
        CHECK (
            updated_at >= created_at
            AND (disabled_at IS NULL OR disabled_at >= created_at)
            AND (disabled_at IS NULL OR updated_at >= disabled_at)
        )
);

CREATE TABLE oidc_identities (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL,
    provider_id uuid NOT NULL,
    subject text NOT NULL,
    linked_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_authenticated_at timestamptz,
    CONSTRAINT oidc_identities_user_fk
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT oidc_identities_provider_fk
        FOREIGN KEY (provider_id) REFERENCES oidc_providers (id) ON DELETE RESTRICT,
    CONSTRAINT oidc_identities_provider_subject_unique UNIQUE (provider_id, subject),
    CONSTRAINT oidc_identities_subject_check
        CHECK (
            subject = btrim(subject)
            AND char_length(subject) BETWEEN 1 AND 1024
        ),
    CONSTRAINT oidc_identities_timestamps_check
        CHECK (
            last_authenticated_at IS NULL
            OR last_authenticated_at >= linked_at
        )
);

CREATE INDEX oidc_identities_user_idx ON oidc_identities (user_id);
